import{_ as l,l as o,o as e,c as s,v as t,p as n,x as i,d as h,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"后量子 Kyber / Dilithium","description":"","frontmatter":{"title":"后量子 Kyber / Dilithium","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/post-quantum-kyber.md","filePath":"cs/post-quantum-kyber.md","lastUpdated":1789023840000}'),c={name:"cs/post-quantum-kyber.md"};function p(u,a,m,S,D,b){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="后量子-kyber-dilithium" tabindex="-1">后量子 Kyber / Dilithium <a class="header-anchor" href="#后量子-kyber-dilithium" aria-label="Permalink to &quot;后量子 Kyber / Dilithium&quot;">​</a></h1><div class="epigraph"><p>Shor 打穿分解与离散对数后，协商要换成 KEM，签名要换成另一类困难问题。ML-KEM（Kyber）与 ML-DSA（Dilithium）是 NIST 标准化的格上候选，不是把 AES 再加长一倍能代替的。</p><footer>—— NIST FIPS 203 ML-KEM；FIPS 204 ML-DSA；Regev, LWE；对照[格与 LWE](/cs/lattice-lwe)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/double-ratchet">双棘轮</a>的 DH 格在量子模型下不再成立。缺口是<strong>换零件</strong>：KEM 封装共享秘密，Dilithium 签。主干<a href="/cs/lattice-lwe">LWE</a>已给困难直觉；本课落到标准化名字与混合迁移，不重推最坏到平均。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ECDH 与 RSA 的长期机密性在大规模量子计算机模型下失败。对称与哈希主要加长。Kyber：封装 32 字节共享秘密；Dilithium：签名体积更大。缺口是协议如何混合：过渡期 ECDHE+Kyber 并行，避免「只部署一种就被其中一种打穿」。</p><h3 id="不是立刻扔掉-ecc" tabindex="-1">不是立刻扔掉 ECC <a class="header-anchor" href="#不是立刻扔掉-ecc" aria-label="Permalink to &quot;不是立刻扔掉 ECC&quot;">​</a></h3><p>迁移是多年工程。证书、HSM、代码体积、失败模式都要改。本课不贩卖恐慌时间表。</p><p><span class="marginnote">FIPS 203/204。Kyber 现名 ML-KEM，Dilithium 现名 ML-DSA。本课不发明 arXiv 编号，不写参数攻击步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 KEM 接口：KeyGen、Encaps、Decaps。签名接口照旧。指出与 HKDF 衔接：KEM 输出仍是 IKM。混合握手：双方都成功才派生。</p>',12)),(e(),n(d,null,{default:i(()=>[E(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEM%5B%22ML-KEM%20%E5%B0%81%E8%A3%85%22%5D%20--%3E%20SS%5B%22%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%22%5D%0A%20%20ECC%5B%22%E8%BF%87%E6%B8%A1%E6%9C%9F%20ECDHE%22%5D%20--%3E%20SS2%5B%22%E7%AC%AC%E4%BA%8C%E4%BB%BD%E7%A7%98%E5%AF%86%22%5D%0A%20%20SS%20--%3E%20MIX%5B%22%E6%B7%B7%E5%90%88%E8%BF%9B%20HKDF%22%5D%0A%20%20SS2%20--%3E%20MIX%0A%20%20MIX%20--%3E%20SK%5B%22%E4%BC%9A%E8%AF%9D%E9%94%AE%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>棘轮仍可在 KEM 上换根，只是「DH 公钥」变成封装密文。身份绑定仍要 PKI 或预共享。格方案公钥和密文更大，带宽与 HSM 固件是工程约束，不是密码分析。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较全部 NIST 轮次淘汰算法。零知识下一课换问题：证明「知道某秘密」而不泄漏，与 KEM 正交。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DH 棘轮的困难问题可被 Shor 打穿；换 KEM。</li><li>ML-KEM / ML-DSA 是标准化格方案。</li><li>过渡期混合派生；输出仍进 HKDF。</li><li>下一课：零知识直觉。</li><li>出处：NIST FIPS 203、FIPS 204；Regev；对照 Shor 的问题范围。</li></ul>',8))])}const M=l(c,[["render",p]]);export{_ as __pageData,M as default};
